"""Fock matrix construction and energy evaluation (pure functions)."""

from __future__ import annotations

from typing import Any

import jax
import jax.numpy as jnp
from jax.scipy.special import xlogy

from .utils import selfenergy_fft


def _herm(X: jax.Array) -> jax.Array:
    """Hermitize on the last two axes."""
    return 0.5 * (X + jnp.conj(jnp.swapaxes(X, -1, -2)))


def _contact_self_energy(
    rho_bar: jax.Array,
    contact_g: jax.Array,
    contact_Oi: jax.Array,
    contact_Oj: jax.Array,
) -> jax.Array:
    """Return the k-independent contact potential generated by ``rho_bar``."""
    tr_Oj_rho = jnp.einsum("tij,ji->t", contact_Oj, rho_bar)
    sigma_h = jnp.einsum("t,tij->ij", contact_g * tr_Oj_rho, contact_Oi)
    sigma_f = -jnp.einsum(
        "t,tij,jk,tkl->il",
        contact_g,
        contact_Oi,
        rho_bar,
        contact_Oj,
    )
    return sigma_h + sigma_f


def build_fock(
    P: jax.Array,
    *,
    h: jax.Array,
    VR: jax.Array,
    refP: jax.Array,
    HH: jax.Array,
    w2d: jax.Array,
    include_exchange: bool,
    include_hartree: bool,
    exchange_hermitian_channel_packing: bool,
    contact_g: jax.Array | None = None,
    contact_Oi: jax.Array | None = None,
    contact_Oj: jax.Array | None = None,
    exchange_block_specs: Any | None = None,
    exchange_check_offdiag: bool | None = None,
    exchange_offdiag_atol: float = 1e-12,
    exchange_offdiag_rtol: float = 0.0,
    project_fn=None,
) -> tuple[jax.Array, jax.Array, jax.Array]:
    """Build Fock matrix and return (Sigma, H_hartree, F).

    F = project(hermitize(h + Sigma[P] + H[P]))

    ``Sigma`` includes the long-range Coulomb exchange (FFT convolution
    with VR) plus, when ``contact_g/Oi/Oj`` are provided, k-independent
    contributions from contact (q-independent) flavor-bilinear terms:
        σ_contact = Σ_t [g_t · O_i_t · tr(O_j_t · ρ̄)
                         - g_t · O_i_t · ρ̄ · O_j_t]
    where ρ̄ = Σ_k w_k (P_k - refP_k).  The interaction energy is
    ½·Tr((Σ+H)·(P−refP)); applying it to the augmented Σ yields the right
    contact energy automatically.
    """
    Sigma = (
        selfenergy_fft(
            VR,
            w2d[..., None, None] * (P - refP),
            block_specs=exchange_block_specs,
            check_offdiag=exchange_check_offdiag,
            offdiag_atol=exchange_offdiag_atol,
            offdiag_rtol=exchange_offdiag_rtol,
            _apply_ifftshift=False,
            hermitian_channel_packing=exchange_hermitian_channel_packing,
        )
        if include_exchange
        else jnp.zeros_like(h)
    )

    if include_hartree:
        dP = P - refP
        diag_real = jnp.real(jnp.diagonal(dP, axis1=-2, axis2=-1))
        n_vec = jnp.sum(w2d[..., None] * diag_real, axis=(0, 1))
        sigma_diag = HH @ n_vec
        H_mat = jnp.diag(sigma_diag.astype(h.real.dtype))
        H = H_mat[None, None, ...]
    else:
        H = jnp.zeros_like(h)

    # Contact (q-independent) flavor-bilinear contributions, k-independent.
    if contact_g is not None and contact_Oi is not None and contact_Oj is not None:
        # ρ̄ = Σ_k w_k (P_k − refP_k), shape (n_orb, n_orb)
        rho_bar = jnp.einsum("ij,ijab->ab", w2d, (P - refP))
        sigma_contact = _contact_self_energy(
            rho_bar, contact_g, contact_Oi, contact_Oj
        ).astype(h.dtype)
        Sigma = Sigma + sigma_contact[None, None, ...]

    F = _herm(h + Sigma + H)
    if project_fn is not None:
        F = _herm(jnp.asarray(project_fn(F), dtype=F.dtype))
    return Sigma, H, F


def hf_energy(
    P: jax.Array,
    *,
    h: jax.Array,
    Sigma: jax.Array,
    H: jax.Array,
    weights_b: jax.Array,
    refP: jax.Array | None = None,
) -> jax.Array:
    """Energy whose derivative is the reference-subtracted Fock matrix.

    ``Sigma + H`` is the linear interaction potential generated by
    ``P - refP``.  Its energy is therefore

        E = <h, P> + 0.5 <Sigma + H, P - refP>,

    where the brackets include the k-point quadrature weights.  ``refP``
    defaults to zero for compatibility with callers that do not use
    reference subtraction.
    """
    dP = P if refP is None else P - refP
    return jnp.sum(
        jnp.real(
            jnp.einsum("...ij,...ji->...", weights_b * h, P)
            + 0.5
            * jnp.einsum(
                "...ij,...ji->...", weights_b * (Sigma + H), dP
            )
        )
    )


def occupation_entropy(p: jax.Array, w_norm: jax.Array) -> jax.Array:
    """S = -sum_k w_k sum_i [p*log(p) + (1-p)*log(1-p)]."""
    p_safe = jnp.clip(p, 0.0, 1.0)
    s = xlogy(p_safe, p_safe) + xlogy(1.0 - p_safe, 1.0 - p_safe)
    return -jnp.sum(w_norm[..., None] * s)


def free_energy(
    E: jax.Array,
    p: jax.Array,
    w_norm: jax.Array,
    T: jax.Array,
) -> jax.Array:
    """Free energy Omega = E - T*S(p)."""
    T_val = jnp.maximum(jnp.asarray(T, dtype=p.dtype), jnp.asarray(1e-14, dtype=p.dtype))
    return E - T_val * occupation_entropy(p, w_norm)
